CREATE OR REPLACE VIEW public.v_cf_drift_dashboard AS WITH stats AS (SELECT (SELECT COUNT(*) FROM cf_recon.cf_image) AS recon_total, (SELECT COUNT(*) FROM public.product_images WHERE deleted_at IS NULL) AS pi_active_total, (SELECT COUNT(*) FROM public.product_images WHERE deleted_at IS NULL AND cf_sync_status = 'verified') AS pi_verified, (SELECT COUNT(*) FROM public.product_images WHERE deleted_at IS NULL AND cf_sync_status = 'orphaned') AS pi_orphaned, (SELECT COUNT(*) FROM public.product_images WHERE deleted_at IS NULL AND cf_sync_status = 'missing') AS pi_missing, (SELECT COUNT(*) FROM public.product_images WHERE deleted_at IS NOT NULL) AS pi_soft_deleted, (SELECT COUNT(*) FROM cf_recon.cf_image c WHERE NOT EXISTS (SELECT 1 FROM public.product_images p WHERE p.cloudflare_image_id = c.image_id AND p.deleted_at IS NULL)) AS cf_orphans_not_in_pi, (SELECT COUNT(*) FROM public.product_images p WHERE p.deleted_at IS NULL AND p.cf_sync_status = 'verified' AND NOT EXISTS (SELECT 1 FROM cf_recon.cf_image c WHERE c.image_id = p.cloudflare_image_id)) AS pi_verified_no_recon, (SELECT COUNT(*) FROM public.image_backfill_queue WHERE status = 'pending') AS backfill_queue_pending) SELECT *, ROUND((pi_verified::numeric / NULLIF(pi_active_total, 0)) * 100, 2) AS pct_verified_active, ROUND((cf_orphans_not_in_pi::numeric / NULLIF(recon_total, 0)) * 100, 2) AS pct_cf_orphans FROM stats; COMMENT ON VIEW public.v_cf_drift_dashboard IS 'Dashboard de drift Cloudflare ↔ product_images. Atualizado 2026-06-17 — Claude.';;
